 static void pickerBinding(){DocxHarness h=setup();h.start();DocxHarness.DocumentDocxExport.last.ready();h.dialog().getButton(-1).tap();Intent old=destination(h);h.start();DocxHarness.DocumentDocxExport.Ticket current=DocxHarness.DocumentDocxExport.last;current.ready();h.dialog().getButton(-1).tap();h.result(-1,old);yes(current.publishes==0&&h.phase().equals("AWAIT_PICKER")&&!current.cancelled,"old picker success A cannot publish newer B");h.result(0,old);yes(current.publishes==0&&h.phase().equals("AWAIT_PICKER")&&!current.cancelled,"old picker cancellation A cannot cancel newer B");h.result(-1,null);h.result(0,new Intent("missing"));h.result(-1,new Intent("oversized").putExtra(NONCE,"x".repeat(4097)));yes(current.publishes==0&&h.phase().equals("AWAIT_PICKER")&&!current.cancelled,"null missing oversized nonce drops without revoking B");h.result(-1,destination(h));yes(current.publishes==1,"authentic B nonce works after stale A");h=setup();h.pickerSecurity=true;h.start();DocxHarness.DocumentDocxExport.Ticket denied=DocxHarness.DocumentDocxExport.last;denied.ready();h.dialog().getButton(-1).tap();yes(denied.cancelled&&!h.phase().equals("AWAIT_PICKER")&&h.dialog().message.contains("picker"),"SecurityException launching proxy cancels invisible pending export");}
 static void capture(){DocxHarness h=setup();DocxHarness.DocumentDocxExport.busy=true;h.start();yes(h.editor.text.copies==0&&h.dialog().message.contains("busy"),"BUSY never reads/copies Editable");DocxHarness.DocumentDocxExport.busy=false;h.start();DocxHarness.DocumentDocxExport.Capture c=DocxHarness.DocumentDocxExport.captured;yes(h.editor.text.copies==1&&c.source.equals("captured source")&&c.title.equals("captured.md")&&c.protectedUris.size()==13,"actual Capture direct Editable source/title/sourceURI plus all12 original tabs");DocxHarness.DocumentDocxExport.Ticket ticket=DocxHarness.DocumentDocxExport.last;h.editor.text.value="new edits";h.displayName="new.md";h.currentUri=Uri.parse("content://source/new");ticket.ready();yes(h.dialog().message.contains("captured.md")&&!h.dialog().message.contains("new edits"),"source-free offer uses captured title");yes(h.dialog().message.contains("1 MiB")&&h.dialog().message.contains("8 MiB")&&h.dialog().message.contains("images"),"visible separate DOCX/native policy and fidelity");h.pickerPause=true;h.dialog().getButton(-1).tap();yes(h.phase().equals("AWAIT_PICKER")&&!ticket.cancelled&&h.pickerRequest==1006&&h.picker.component==DocxPickerActivity.class&&h.picker.title.equals("captured.docx")&&h.picker.flags==0&&h.picker.extras.size()==2,"mark awaited before picker-induced pause");for(int i=0;i<12;i++)h.tabs.get(i).uri="content://current/tab-"+i;h.result(-1,destination(h));yes(ticket.publishes==1&&ticket.current.size()==12&&ticket.current.get(11).toString().equals("content://current/tab-11"),"all12 current tabs passed to coordinator union");h.result(-1,destination(h));yes(ticket.publishes==1,"duplicate picker result no second publish");ticket.done(true,null);yes(h.dialog().message.contains("verified")&&h.dirty&&h.baselineHash.equals("baseline")&&h.currentUri.toString().equals("content://source/new")&&h.historyChanges==0&&h.recentChanges==0&&h.editor.text.value.equals("new edits"),"verified only success leaves native state unchanged");}
 static void lifecycle(){DocxHarness h=setup();h.start();DocxHarness.DocumentDocxExport.Ticket old=DocxHarness.DocumentDocxExport.last;Consumer<DocxHarness.DocumentDocxExport.Offer> late=old.ready;h.trace.clear();h.pause();yes(old.cancelled&&h.phase().equals("NONE")&&h.trace.indexOf("session")<h.trace.indexOf("cancel")&&h.trace.indexOf("recovery")<h.trace.indexOf("cancel"),"generating pause saves first then cancels");h.start();DocxHarness.AlertDialog current=h.dialog();late.accept(new DocxHarness.DocumentDocxExport.Offer("stale"));yes(h.dialog()==current,"late READY cannot replace newer UI");DocxHarness.DocumentDocxExport.last.ready();DocxHarness.AlertDialog offer=h.dialog();h.pause();offer.getButton(-1).tap();yes(h.launches==0,"paused offer stale positive inert");h.start();DocxHarness.DocumentDocxExport.Ticket ticket=DocxHarness.DocumentDocxExport.last;ticket.ready();h.dialog().getButton(-1).tap();h.result(-1,destination(h));Consumer<DocxHarness.DocumentDocxExport.Completion> lateDone=ticket.completion;h.pause();yes(ticket.cancelled&&h.phase().equals("NONE"),"publishing pause cancels callbacks");lateDone.accept(new DocxHarness.DocumentDocxExport.Completion(true,null));yes(h.dialog()==null,"canceled late DONE cannot claim success");h.resume();yes(h.dialog().message.contains("incomplete")&&!h.dialog().message.contains("verified"),"interrupted publishing honest bounded resume notice");h.start();ticket=DocxHarness.DocumentDocxExport.last;ticket.ready();h.dialog().getButton(-1).tap();h.destroy();h.result(-1,destination(h));yes(ticket.cancelled&&ticket.publishes==0,"destroy while picker pending unbinds result");DocxHarness recreated=setup();recreated.result(-1,destination(recreated));yes(recreated.phase().equals("NONE"),"recreated unbound result never publishes");}
 static void staleAndBad(){DocxHarness h=setup();h.start();DocxHarness.DocumentDocxExport.Ticket first=DocxHarness.DocumentDocxExport.last;first.ready();DocxHarness.AlertDialog old=h.dialog();h.start();old.getButton(-1).tap();yes(first.cancelled&&h.launches==0,"replaced offer cannot launch picker");DocxHarness.DocumentDocxExport.last.ready();old=h.dialog();old.dismiss();old.getButton(-1).tap();yes(h.launches==0&&h.phase().equals("NONE"),"dismissed offer cannot launch");h.start();DocxHarness.DocumentDocxExport.last.ready();h.dialog().getButton(-1).tap();DocxHarness.DocumentDocxExport.Ticket t=DocxHarness.DocumentDocxExport.last;h.result(0,new Intent().putExtra(NONCE,h.picker.getStringExtra(NONCE)));yes(t.cancelled&&t.publishes==0,"canceled picker no publish");h.start();t=DocxHarness.DocumentDocxExport.last;t.ready();h.dialog().getButton(-1).tap();h.result(-1,new Intent().putExtra(NONCE,h.picker.getStringExtra(NONCE)));yes(t.cancelled&&t.publishes==0,"null result no publish");h.start();t=DocxHarness.DocumentDocxExport.last;t.ready();h.dialog().getButton(-1).tap();h.tabs.get(11).uri="file:///bad";h.result(-1,destination(h));yes(t.publishes==0&&t.cancelled,"malformed current nonnull URI refuses without publish");h=setup();h.tabs.add(new DocxHarness.DocumentTab(null));h.start();yes(h.editor.text.copies==0&&h.dialog().message.contains("could not"),"over12 actual tabs never truncate or capture");h=setup();h.editor.text.value="x".repeat(1048577);h.start();yes(h.editor.text.copies==0,"oversize Editable validated before copy");h=setup();h.tabs.get(0).uri=null;h.start();yes(DocxHarness.DocumentDocxExport.captured.protectedUris.size()==12,"genuinely untitled URI omitted");h.pickerFails=true;DocxHarness.DocumentDocxExport.last.ready();h.dialog().getButton(-1).tap();yes(DocxHarness.DocumentDocxExport.last.cancelled&&h.dialog().message.contains("picker"),"missing picker cancels capability");}
 static void guards(){DocxHarness h=setup();h.start();DocxHarness.DocumentDocxExport.Ticket t=DocxHarness.DocumentDocxExport.last;Consumer<DocxHarness.DocumentDocxExport.Failure> failed=t.failure;DocxHarness.AlertDialog old=h.dialog();h.start();DocxHarness.AlertDialog current=h.dialog();old.getButton(-2).tap();failed.accept(new DocxHarness.DocumentDocxExport.Failure(DocxHarness.DocumentDocxExport.Problem.GENERATION,false));yes(h.dialog()==current,"old cancel/failure cannot revoke replacement");DocxHarness.DocumentDocxExport.last.failure.accept(new DocxHarness.DocumentDocxExport.Failure(DocxHarness.DocumentDocxExport.Problem.GENERATION,false));yes(h.dialog().message.contains("could not be prepared"),"current generation failure shown honestly");h.start();t=DocxHarness.DocumentDocxExport.last;h.dialog().getButton(-2).tap();yes(t.cancelled&&t.ready==null&&t.failure==null&&h.phase().equals("NONE"),"explicit cancel clears ticket callbacks and UI");h.start();t=DocxHarness.DocumentDocxExport.last;t.ready();h.dialog().getButton(-1).tap();h.result(-1,new Intent("result").putExtra(NONCE,h.picker.getStringExtra(NONCE)).setData(Uri.parse("file:///bad")));yes(t.publishes==0&&t.cancelled,"malformed destination never publishes");}
 static void entriesAndWarnings(){DocxHarness h=setup();yes(h.menu(17)&&h.phase().equals("GENERATING"),"actual appended overflow17 dispatch");h.pause();h.command(16);yes(h.phase().equals("GENERATING"),"actual appended palette16 dispatch");h.pause();h.workspace();yes(h.phase().equals("GENERATING"),"actual visible Workspace action");DocxHarness.DocumentDocxExport.Offer offer=new DocxHarness.DocumentDocxExport.Offer("title");for(DocxHarness.MarkdownDocx.Warning warning:DocxHarness.MarkdownDocx.Warning.values())offer.warnings.put(warning,1);DocxHarness.DocumentDocxExport.last.ready.accept(offer);yes(h.dialog().message.contains("Unsupported links")&&h.dialog().message.contains("Ambiguous tables")&&h.dialog().message.contains("Ambiguous lists")&&h.dialog().message.contains("Unclosed code")&&h.dialog().message.contains("Unsupported inline")&&h.dialog().message.contains("Unsupported blocks"),"all warning kinds have bounded readable labels");for(DocxHarness.DocumentDocxExport.Problem p:DocxHarness.DocumentDocxExport.Problem.values()){h=setup();h.start();DocxHarness.DocumentDocxExport.Ticket t=DocxHarness.DocumentDocxExport.last;t.ready();h.dialog().getButton(-1).tap();h.result(-1,destination(h));t.done(false,new DocxHarness.DocumentDocxExport.Failure(p,true));yes(!h.dialog().message.contains("was verified")&&h.dialog().message.contains("incomplete"),"every false completion is honest "+p);}}
 static void errorsAndThemes(){for(int theme=0;theme<9;theme++){DocxHarness h=setup();h.palette=UiTheme.palette(theme,false);h.start();DocxHarness.DocumentDocxExport.Ticket t=DocxHarness.DocumentDocxExport.last;DocxHarness.DocumentDocxExport.Offer offer=new DocxHarness.DocumentDocxExport.Offer("captured.md");offer.warnings.put(DocxHarness.MarkdownDocx.Warning.IMAGE_NOT_INCLUDED,2);t.ready.accept(offer);DocxHarness.AlertDialog d=h.dialog();yes(d.customTitle.color==h.palette.text&&d.messageView.color==h.palette.text&&((GradientDrawable)d.window.background).color==h.palette.raised,"actual themed offer "+theme);yes(d.getButton(-1).color==UiTheme.readableForeground(h.palette.accent,h.palette.raised)&&d.message.contains("2"),"actual themed actions and bounded warning count "+theme);d.getButton(-1).tap();h.result(-1,destination(h));t.done(false,new DocxHarness.DocumentDocxExport.Failure(DocxHarness.DocumentDocxExport.Problem.UNCERTAIN_IO,true));yes(h.dialog().message.contains("restart")&&h.dialog().message.contains("incomplete")&&!h.dialog().message.contains("close and reopen"),"honest uncertain failure "+theme);}}
